using System.IO.Compression;
using System.Security.Cryptography;
using System.Text;
using System.Text.Json;

namespace TabletDeck;
public static class StudioTests
{
    public static async Task Run(){
        var passed=0;void Check(bool value,string message){if(!value)throw new Exception("FAIL "+message);passed++;Console.WriteLine("PASS "+message);}
        void Reject(Action call,string message){try{call();throw new Exception("Accepted: "+message);}catch(ArgumentException){Check(true,message);}}
        var root=Path.Combine(Path.GetTempPath(),"tabletdeck-studio-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(root);
        try{
            var store=new DataStore(root);var initial=store.Config.ProfileId;var second=store.CreateProfile("Second",true);
            using var rules=new AutoProfiles(root,id=>store.ProfileList().Any(p=>p.Id==id),id=>{store.SwitchProfile(id);return true;});
            rules.Save(new(true,[new("obs64.exe",second)]));var now=DateTimeOffset.UtcNow;rules.Tick("obs64.exe",now);Check(store.Config.ProfileId==initial,"automatic profiles wait for foreground debounce");rules.Tick("obs64.exe",now.AddSeconds(1));Check(store.Config.ProfileId==initial,"one second cannot switch a profile");rules.Tick("obs64.exe",now.AddSeconds(2));Check(store.Config.ProfileId==second,"stable app selects its configured profile");rules.Tick("other.exe",now.AddSeconds(5));Check(store.Config.ProfileId==second,"unmatched app keeps current profile");
            Reject(()=>rules.Save(new(true,[new("obs64.exe",initial),new("OBS64.EXE",second)])),"automatic rules reject duplicate executable names");Reject(()=>rules.Save(new(true,[new("..\\bad.exe",initial)])),"automatic rules reject path/command input");Reject(()=>rules.Save(new(true,[new("test.exe",Guid.NewGuid().ToString("N"))])),"automatic rules reject missing profile");
            using var restoredRules=new AutoProfiles(root,_=>true,_=>false);Check(JsonSerializer.Serialize(restoredRules.Snapshot(),DataStore.Json).Contains("obs64.exe"),"automatic rules persist privately");
            var paused=false;using var pauseRules=new AutoProfiles(Path.Combine(root,"pause"),_=>true,_=>{paused=true;return false;});Directory.CreateDirectory(Path.Combine(root,"pause"));pauseRules.Save(new(true,[new("game.exe",initial)]));pauseRules.Tick("game.exe",now);pauseRules.Tick("game.exe",now.AddSeconds(2));Check(paused&&JsonSerializer.Serialize(pauseRules.Snapshot()).Contains("paused"),"blocked automatic switch reports paused status");
            await using var obs=new ObsClient(()=>store.Config);using var holds=new HoldKeys((_,_)=>{},()=>DateTimeOffset.UtcNow);using var mixer=new AppAudioMixer();var engine=new DeckEngine(store,obs);var commands=new FastCommands(store,engine,holds,mixer);
            commands.ProfileLock("fixture",true);Check(!commands.AutoProfile(initial)&&store.Config.ProfileId==second,"editing lease blocks automatic switch");commands.ProfileLock("fixture",false);var lease=holds.Begin("fixture","F13");Check(!commands.AutoProfile(initial),"held keys block automatic switch");holds.Release("fixture",lease);Check(commands.AutoProfile(initial)&&store.Config.ProfileId==initial,"released editing/hold permits auto switch");commands.ManualProfile(second);Check(!commands.AutoProfile(initial),"manual switch suppresses automatic selection for thirty seconds");
            var key=new string('A',64);for(var i=0;i<35;i++)store.RecordRecent(new(i+1,"Sound "+i,"","",[],i.ToString("X64")));Check(store.Recents().Length==30,"recent sounds are bounded to thirty distinct identities");store.RecordRecent(new(99,"Renamed","","",[],key));store.RecordRecent(new(100,"Renamed again","","",[],key));Check(store.Recents().Count(s=>s.Key==key)==1&&store.Recents()[0].Name=="Renamed again","recent history deduplicates stable identities and moves replay to front");Check(new DataStore(root).Recents()[0].Key==key,"recent sounds survive restart");store.ClearRecents();Check(store.Recents().Length==0&&store.Favourites().Length==0,"clear recent history leaves configuration intact");
            var fakeSound=new LibrarySound(52,"Fixture sound","","",[],key);var fakeLibrary=new SoundpadLibraryResult([fakeSound],null);string? played=null;
            var fakeEngine=new DeckEngine(store,obs,(_,target,_,_)=>{played=target;return Task.CompletedTask;},_=>Task.FromResult(fakeLibrary));
            await fakeEngine.Execute(new(){Kind="soundpadPlay",Target="1",SoundpadKey=key});Check(played=="52"&&store.Recents()[0].Key==key,"successful Soundpad play records current stable identity after resolving reordered index");
            store.ClearRecents();var failedEngine=new DeckEngine(store,obs,(_,_,_,_)=>throw new IOException("Fixture playback rejected"),_=>Task.FromResult(fakeLibrary));try{await failedEngine.Execute(new(){Kind="soundpadPlay",Target="1",SoundpadKey=key});}catch(IOException){}Check(store.Recents().Length==0,"failed Soundpad playback never enters recent history");
            StudioTools.ValidateMixer([new(Guid.NewGuid().ToString("N"),"Music","Music input")]);Check(true,"additional mixer channel validates");Reject(()=>StudioTools.ValidateMixer([new("mic","Bad","Input")]),"extra mixer cannot replace a main channel identity");Reject(()=>StudioTools.ValidateMixer(Enumerable.Range(0,9).Select(i=>new MixerChannel(Guid.NewGuid().ToString("N"),"Extra","Input")).ToArray()),"extra mixer is bounded to eight channels");
            var channel=new MixerChannel(Guid.NewGuid().ToString("N"),"Music","Exact input");store.Modify(c=>c.MixerInputs=[channel]);Check(engine.Input(channel.Id)=="Exact input","mixer command resolves only configured channel identity");Reject(()=>engine.Input("arbitrary-input"),"mixer rejects arbitrary input identities");
            Reject(()=>StudioTools.ValidateIcon("data:image/svg+xml;base64,AAA"),"custom icons reject SVG/active content");Reject(()=>StudioTools.ValidateIcon("data:image/png;base64,???"),"custom icons reject malformed PNG");
            var png=Convert.FromBase64String(PairingQr.Image(PairingQr.Payload("192.168.1.2","wifi","123456",new string('A',24),8743,8744))[22..]);
            using(var stream=new MemoryStream()) {using(var source=System.Drawing.Image.FromStream(new MemoryStream(png)))source.Save(stream,System.Drawing.Imaging.ImageFormat.Png);var image="data:image/png;base64,"+Convert.ToBase64String(stream.ToArray());if(sourceWidth(png)<=512){StudioTools.ValidateIcon(image);Check(true,"valid locally generated PNG passes icon validation");}}
            Check(PairingQr.Payload("127.0.0.1","usb","123456",new string('A',24),19083,19084).Contains("controlPort=19084"),"QR carries both authenticated transport ports");Reject(()=>PairingQr.Payload("8.8.8.8","wifi","123456",new string('A',24),8743,8744),"QR refuses public PC addresses");Reject(()=>PairingQr.Payload("127.0.0.1","usb","bad",new string('A',24),8743,8744),"QR refuses invalid PIN");
            var audio=Path.Combine(root,"sample.wav");File.WriteAllBytes(audio,Encoding.ASCII.GetBytes("RIFF-fixture-not-played"));store.Modify(c=>{c.ObsPassword="private-fixture-secret";c.Pages[0].Buttons.Add(new(){Kind="sound",Label="Included",Target=audio});c.Pages[0].Buttons.Add(new(){Kind="macro",Label="Nested",Steps=[new(){Kind="sound",Label="Nested sound",Target=audio},new(){Kind="app",Label="App",Target=Path.Combine(root,"not-shipped.exe")}]});});
            var packs=new BoardPacks(store);var manifest=JsonSerializer.SerializeToElement(packs.Manifest(store.Config.ProfileId),DataStore.Json);var soundId=manifest.GetProperty("sounds").EnumerateArray().Single(s=>s.GetProperty("path").GetString()==audio).GetProperty("id").GetString()!;var archive=packs.Export(store.Config.ProfileId,[soundId]);
            Check(!Encoding.UTF8.GetString(archive).Contains("private-fixture-secret"),"portable archive never contains OBS credentials");
            using(var zip=new ZipArchive(new MemoryStream(archive))){Check(zip.Entries.Count==2&&zip.Entries.All(e=>e.FullName=="manifest.json"||e.FullName.StartsWith("sounds/",StringComparison.Ordinal)),"pack includes only metadata and explicitly selected sound");using var stream=zip.GetEntry("manifest.json")!.Open();var pack=JsonSerializer.Deserialize<BoardPack>(stream,DataStore.Json)!;Check(BoardPacks.Actions(pack.Pages).Where(a=>a.Kind=="app").All(a=>a.Target==""),"export clears app targets including nested macros");Check(BoardPacks.Actions(pack.Pages).Count(a=>a.Target.StartsWith("pack:",StringComparison.Ordinal))==2,"pack rewrites repeated and nested sound references");}
            var preview=JsonSerializer.SerializeToElement(packs.Preview(archive),DataStore.Json);var imported=packs.Import(preview.GetProperty("id").GetString()!,"Imported");Check(store.Config.ProfileId==second&&store.Config.Profiles.Any(p=>p.Id==imported),"pack imports as an inactive profile");var importedBoard=store.Config.Profiles.Single(p=>p.Id==imported);var importedSound=BoardPacks.Actions(importedBoard.Pages).First(a=>a.Label=="Included");Check(File.ReadAllBytes(importedSound.Target).SequenceEqual(File.ReadAllBytes(audio))&&Path.GetFullPath(importedSound.Target).StartsWith(Path.Combine(root,"pack-assets")+Path.DirectorySeparatorChar,StringComparison.OrdinalIgnoreCase),"bundled sound extracts only to generated private asset directory");Check(!store.Config.Pages.SelectMany(p=>p.Buttons).Any(a=>a.Id==importedSound.Id),"import regenerates action identities");Check(store.Config.ObsPassword=="private-fixture-secret","pack import preserves local credentials");Reject(()=>packs.Import(preview.GetProperty("id").GetString()!,"Again"),"consumed pack preview cannot import twice");
            byte[] ChangeZip(string name,byte[] content){using var output=new MemoryStream();using(var zip=new ZipArchive(output,ZipArchiveMode.Create,true)){using(var original=new ZipArchive(new MemoryStream(archive))){foreach(var entry in original.Entries){using var src=entry.Open();using var dest=zip.CreateEntry(entry.FullName).Open();src.CopyTo(dest);}}using var extra=zip.CreateEntry(name).Open();extra.Write(content);}return output.ToArray();}
            Reject(()=>packs.Preview(ChangeZip("../escape.wav",[1])),"pack rejects traversal or unexpected zip entries");Reject(()=>packs.Preview(ChangeZip("manifest.json",[1])),"pack rejects duplicate zip entries");Reject(()=>packs.Export(store.Config.ProfileId,[new string('F',64)]),"pack export cannot include an arbitrary file reference");
            var noSounds=packs.Export(store.Config.ProfileId,[]);Check(JsonSerializer.Serialize(packs.Preview(noSounds),DataStore.Json).Contains("unbundled sounds"),"metadata-only pack imports with an explicit missing-sound warning");
            foreach(var kind in new[]{"streamStart","streamStop","recordStart","recordStop"}){var action=new DeckAction{Kind=kind};DataStore.CheckAction(action);Check(DeckEngine.NeedsConfirm(action),kind+" always requires confirmation");}
            Check(DeckEngine.NeedsConfirm(new(){Kind="macro",Steps=[new(){Kind="recordStart"}]}),"explicit broadcast action still requires confirmation inside macro");
            Console.WriteLine(passed+" studio storage/safety checks passed; no GUI, audio, real Soundpad or foreground-app query used.");
        }finally{foreach(var file in Directory.EnumerateFiles(root,"*",SearchOption.AllDirectories))File.Delete(file);foreach(var dir in Directory.EnumerateDirectories(root,"*",SearchOption.AllDirectories).OrderByDescending(p=>p.Length))Directory.Delete(dir);Directory.Delete(root);}
        static int sourceWidth(byte[] png){using var stream=new MemoryStream(png);using var bitmap=System.Drawing.Image.FromStream(stream);return bitmap.Width;}
    }
}
